// The Brass corners mark and the kist wordmark, inline so they take the
// theme's colours (paths: brandPaths.ts, generated by docs/brand/build_brand.py).

import { MARK_PATH, WORDMARK } from '../brandPaths'

/** The mark alone. Decorative unless given a label. */
export function Mark({ className = 'brand-mark', label }: { className?: string; label?: string }) {
  return (
    <svg
      className={className}
      viewBox="0 0 64 64"
      fill="currentColor"
      role={label ? 'img' : undefined}
      aria-label={label}
      aria-hidden={label ? undefined : true}
      focusable="false"
    >
      <path d={MARK_PATH} />
    </svg>
  )
}

/** Lowercase "kist" in Instrument Serif with the brass square i-dot. */
export function Wordmark({ className = 'wordmark', label = 'Kist' }: { className?: string; label?: string | null }) {
  const { dot } = WORDMARK
  return (
    <svg
      className={className}
      viewBox={WORDMARK.viewBox}
      fill="currentColor"
      role={label ? 'img' : undefined}
      aria-label={label ?? undefined}
      aria-hidden={label ? undefined : true}
      focusable="false"
    >
      <path d={WORDMARK.ink} />
      <rect className="dot" x={dot.x} y={dot.y} width={dot.size} height={dot.size} rx={dot.size * 0.08} />
    </svg>
  )
}

/** The mark drawn in outline, for empty states (B17): the two brackets as
 * thin lines, the kept item a brass square. Always decorative. */
export function OutlineMark({ className = 'outline-mark' }: { className?: string }) {
  return (
    <svg className={className} viewBox="0 0 64 64" aria-hidden="true" focusable="false">
      <path d="M8 26V10a2 2 0 0 1 2-2h16M56 38v16a2 2 0 0 1-2 2H38" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" />
      <rect className="dot" x="28" y="28" width="8" height="8" rx="1.5" />
    </svg>
  )
}
